cat > internal/ui/components/field_clamp.go <<'EOF'
package components

import (
	"strings"

	"github.com/charmbracelet/x/ansi"
)

func ClampField(rendered string, width int) string {
	if ansi.StringWidth(rendered) <= width {
		return rendered
	}
	var b strings.Builder
	used := 0
	styled := false
	rest := rendered
	for rest != "" {
		if rest[0] == 0x1b {
			// copy the sequence
			n := len(rest) - len(ansi.Strip(rest))
			_ = n
			end := strings.IndexByte(rest, 'm')
			seq := rest[:end+1]
			b.WriteString(seq)
			styled = seq != "\x1b[0m" && seq != "\x1b[m"
			rest = rest[end+1:]
			continue
		}
		c, w := ansi.FirstGraphemeCluster(rest, ansi.GraphemeWidth)
		if used+w > width {
			break
		}
		b.WriteString(c)
		used += w
		rest = rest[len(c):]
	}
	if styled {
		b.WriteString("\x1b[0m")
	}
	return b.String()
}
EOF
